<!-- This file is generated by AI. -->

<!--
  视频导出对话框。

  表单**复用** `ui/` 里的既有控件 (`Input` / `Select` / `Checkbox` / `Button`) 与 `styles.css`
  的 `.settings-*` 规则, 结构跟设置对话框、快照对话框一致: `.settings-group` + `.settings-field`
  + `.settings-label`。不要在这里自绘 input / checkbox —— 原生控件不参与主题, 会出现"右边浮着一个
  小方块"的那种观感。

  参数分四组, 对应"输出 → 路线 → 画面 → 演出"的心智模型:
  - 画面 = 视频编码参数 (分辨率 / 帧率 / 码率 / 编码);
  - 演出 = 字号、两个速度、导出内容、立绘方位判定、滤镜与图层开关。
  开关一律用肯定式 (勾选 = 有), 否定语义只在提交时翻译成后端字段
  (`audioOnly` / `disableFilters` / `uiOnly` / `stageOnly`)。
  两个速度的语义与 WebGAL 一致 (0..100, 越大越快), 默认 12 / 24。

  导出开始后对话框**不关闭、也不回到表单**: 左列实时显示渲染器推来的预览帧与进度,
  右列保留本次导出的参数摘要; 底部按钮变成"取消"。完成/失败后仍停在这一屏。

  组件相关 (Live2D Core 导入) **不在这里**: 它是全局设置, 放在「设置 → 渲染 → 视频导出」。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { listen, type UnlistenFn } from '@tauri-apps/api/event';
  import { save } from '@tauri-apps/plugin-dialog';
  import { revealItemInDir } from '@tauri-apps/plugin-opener';
  import { onMount, untrack } from 'svelte';

  import {
    cancelVideoExport,
    exportVideo,
    videoExportStatus,
    videoProjectInfo,
    videoRoutePreview,
    type RouteNode,
    type VideoExportProgress,
    type VideoExportPreview,
    type VideoExportStatus,
  } from '../commands/videoExport';
  import { actions, appStore } from '../state/store.svelte';
  import { joinPath } from '../lib/paths';
  import { presetWidth, resolutionOptions } from '../lib/video-preset';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Checkbox from './Checkbox.svelte';
  import Input from './Input.svelte';
  import Select from './Select.svelte';

  let { onClose }: { onClose: () => void } = $props();

  const projectPath = $derived(appStore.projectPath);
  const projectName = $derived(appStore.projectName ?? 'project');

  const ENCODER_OPTIONS = [
    { value: 'auto', label: '自动' },
    { value: 'mf', label: 'Media Foundation' },
    { value: 'ffmpeg', label: '外部 ffmpeg' },
  ];

  /** 码率只给三档预设, 标签里用括号写明实际值 —— 让用户填一个数字没有意义。 */
  const BITRATE_OPTIONS = [
    { value: '4000', label: '低（4 Mbps）' },
    { value: '8000', label: '中（8 Mbps）' },
    { value: '16000', label: '高（16 Mbps）' },
  ];

  const FONT_SCALE_OPTIONS = [
    { value: '0.85', label: '小' },
    { value: '1', label: '中' },
    { value: '1.15', label: '大' },
  ];

  /**
   * `changeFigure` 的立绘身份判定。
   *
   * 不勾选 = 4.6.3 及以前（只看图片地址，省略位置沿用旧基准）；
   * 勾选 = 4.6.4+（位置也参与判定，省略位置 = center）。
   */

  /** 导出内容用一个下拉表达, 取代原来的两个独立勾选框。 */
  const CONTENT_OPTIONS = [
    { value: 'video-audio', label: '视频 + 音频' },
    { value: 'video', label: '仅视频画面' },
    { value: 'audio', label: '仅音频（WAV）' },
  ];

  const KIND_LABELS: Record<string, string> = {
    changeScene: '切换场景',
    choose: '选项',
    callScene: '调用场景',
  };

  let scenes = $state<string[]>([]);
  let startScene = $state('start.txt');
  let status = $state<VideoExportStatus | null>(null);
  let route = $state<RouteNode[]>([]);
  let selected = $state<Record<string, number>>({});
  let phase = $state<'idle' | 'working' | 'done' | 'failed'>('idle');
  let errors = $state<string[]>([]);
  let notice = $state('');

  let output = $state('');

  /* 上次使用的参数从用户设置恢复; 没有记录时用默认值。 */
  const stored = appStore.settings.videoExport;

  /* 舞台尺寸用于把 720p/1080p… 换算成实际宽高; 默认按 WebGAL 的 2560×1440。 */
  let stageWidth = $state(2560);
  let stageHeight = $state(1440);
  let resolution = $state(stored.resolution);

  /* 数值参数用字符串草稿: 输入过程中允许暂时为空/越界, 提交时才夹到范围内。 */
  let fpsText = $state(stored.fps);
  let bitrate = $state(stored.bitrate);
  let encoder = $state(stored.encoder);
  /* 自动编码实际选中哪个后端由渲染器回调报告, 不能靠猜。 */
  let actualEncoder = $state('');

  let fontScale = $state(stored.fontScale);
  let autoSpeedText = $state(stored.autoSpeed);
  let textSpeedText = $state(stored.textSpeed);
  /* 勾选 = 4.6.4+ 的立绘方位判定; 不勾选 = 4.6.3 及以前。 */
  let figureSideModern = $state(stored.figureSide === 'modern');

  /* 输出内容: 一个下拉同时决定视频轨、音频轨和产物扩展名。 */
  let contentMode = $state(stored.content);
  const exportVideoClip = $derived(contentMode !== 'audio');
  const includeAudio = $derived(contentMode !== 'video');
  let enableFilters = $state(stored.enableFilters);
  let includeStage = $state(stored.includeStage);
  let includeUi = $state(stored.includeUi);

  /* 导出进度: 事件来自渲染器的逐帧回调 (约 1 秒一帧预览 + 每 10 帧一次进度)。 */
  let previewUrl = $state('');
  let progressCurrent = $state(0);
  let progressTotal = $state(0);
  let progressFps = $state(0);
  let startedAt = $state(0);
  let finishedAt = $state(0);
  let tick = $state(0);
  let cancelRequested = $state(false);
  let resultPath = $state('');

  const busy = $derived(phase === 'working');
  const canExport = $derived(Boolean(status?.supported) && output.trim().length > 0 && !busy);
  const percent = $derived(
    phase === 'done'
      ? 100
      : progressTotal > 0
        ? Math.max(0, Math.min(100, Math.round((progressCurrent / progressTotal) * 100)))
        : 0
  );
  const elapsedSeconds = $derived.by(() => {
    if (startedAt === 0) return 0;
    void tick;
    // 完成/失败后计时停住, 不再随 wall clock 增长。
    const end = finishedAt > 0 ? finishedAt : Date.now();
    return Math.max(0, (end - startedAt) / 1000);
  });
  function formatDuration(seconds: number): string {
    const value = Math.max(0, Math.round(seconds));
    return `${Math.floor(value / 60)}:${String(value % 60).padStart(2, '0')}`;
  }
  const elapsedText = $derived(formatDuration(elapsedSeconds));
  /** 按当前吞吐估算剩余时间 (只在实际渲染阶段显示)。 */
  const etaText = $derived.by(() => {
    if (phase !== 'working' || progressCurrent <= 0 || progressTotal <= 0) return '';
    const remaining = (Math.max(0, progressTotal - progressCurrent) / progressCurrent) * elapsedSeconds;
    return `剩余约 ${formatDuration(remaining)}`;
  });
  const bitrateLabel = $derived(BITRATE_OPTIONS.find((item) => item.value === bitrate)?.label ?? bitrate);
  const encoderLabel = $derived(ENCODER_OPTIONS.find((item) => item.value === encoder)?.label ?? encoder);
  /** 配置栏写清楚"自动"到底优先用什么。 */
  const encoderSummary = $derived(
    encoder === 'auto' ? (actualEncoder ? `自动（${actualEncoder}）` : '自动（导出时探测）') : encoderLabel
  );
  const speedSummary = $derived(`文字 ${textSpeedText} · 自动 ${autoSpeedText}`);
  /* 分辨率只给高度预设; 画幅跟随 game/config.txt 的舞台宽高比。 */
  const resolutionChoices = $derived(resolutionOptions(stageWidth, stageHeight));
  const outputWidth = $derived(presetWidth(Number(resolution), stageWidth, stageHeight));
  const outputHeight = $derived(Number(resolution));
  const contentLabel = $derived(
    CONTENT_OPTIONS.find((item) => item.value === contentMode)?.label ?? CONTENT_OPTIONS[0].label
  );
  const layerSummary = $derived(
    [includeStage ? '舞台画面' : '', includeUi ? '文本框与选项' : ''].filter((item) => item.length > 0).join(' + ') ||
      '无'
  );
  const fontScaleLabel = $derived(FONT_SCALE_OPTIONS.find((item) => item.value === fontScale)?.label ?? fontScale);
  /* 自动模式的摘要写清解析结果，避免“自动”变成一个黑盒。 */

  /* 配置摘要里的路线: 只列场景, 按顺序用箭头连起来。 */
  const routeChain = $derived.by(() => {
    const names = [
      startScene,
      ...route.map((node) => node.target).filter((target): target is string => target !== null),
    ];
    return names.join(' → ');
  });

  /* 参数改动即写回用户设置; 下次打开/重启后恢复。用 untrack 避免 updateSettings
     读取 appStore 又把 effect 注册成依赖。 */
  $effect(() => {
    const preferences = {
      resolution,
      fps: fpsText,
      bitrate,
      encoder,
      content: contentMode,
      fontScale,
      autoSpeed: autoSpeedText,
      textSpeed: textSpeedText,
      figureSide: figureSideModern ? 'modern' : 'legacy',
      enableFilters,
      includeStage,
      includeUi,
    };
    untrack(() => actions.updateSettings({ videoExport: preferences }));
  });

  let timer: ReturnType<typeof setInterval> | undefined;

  onMount(() => {
    const unlisteners: UnlistenFn[] = [];
    void (async () => {
      unlisteners.push(
        await listen<VideoExportProgress>('video-export:progress', (event) => {
          if (phase !== 'working') return;
          // 音频阶段也会发进度, 但 total 是音频事件数 (常见 5), 不能覆盖视频帧总数。
          if (event.payload.phase !== 'render') return;
          progressCurrent = event.payload.current;
          progressTotal = event.payload.total;
          progressFps = event.payload.fps;
        })
      );
      unlisteners.push(
        await listen<VideoExportPreview>('video-export:preview', (event) => {
          if (phase !== 'working') return;
          previewUrl = event.payload.data;
          if (event.payload.total > 0) progressTotal = event.payload.total;
          if (event.payload.frame > progressCurrent) progressCurrent = event.payload.frame;
        })
      );
      unlisteners.push(
        await listen<string>('video-export:encoder', (event) => {
          if (phase !== 'working') return;
          actualEncoder = event.payload;
        })
      );
    })();
    timer = setInterval(() => {
      tick += 1;
    }, 500);
    if (projectPath) {
      const extension = contentMode === 'audio' ? '.wav' : '.mp4';
      output = joinPath(projectPath, `${projectName}-video${extension}`);
      void refresh();
    }
    return () => {
      for (const unlisten of unlisteners) unlisten();
      if (timer) clearInterval(timer);
    };
  });

  async function refresh(): Promise<void> {
    if (!projectPath) return;
    try {
      const [info, exportStatus] = await Promise.all([videoProjectInfo(projectPath), videoExportStatus()]);
      scenes = info.scenes;
      startScene = info.startScene;
      if (info.stageWidth >= 64 && info.stageHeight >= 64) {
        stageWidth = info.stageWidth;
        stageHeight = info.stageHeight;
      }
      status = exportStatus;
      await refreshRoute();
    } catch (error) {
      errors = [String(error)];
      phase = 'failed';
    }
  }

  async function refreshRoute(): Promise<void> {
    if (!projectPath) return;
    try {
      const preview = await videoRoutePreview(projectPath, startScene, selected);
      route = preview.nodes;
    } catch (error) {
      errors = [...errors, String(error)];
    }
  }

  function changeStartScene(next: string): void {
    startScene = next;
    // 换起始场景后, 旧的分支选择可能已经不存在了
    selected = {};
    void refreshRoute();
  }

  function chooseOption(node: RouteNode, value: string): void {
    const index = Number(value);
    selected = { ...selected, [`${node.scene}:${node.line}`]: index };
    void refreshRoute();
  }

  /** 只导出音频时产物是 WAV, 扩展名跟着切, 免得拿到一个叫 .mp4 的音频文件。 */
  function changeContentMode(next: string): void {
    contentMode = next as typeof contentMode;
    const extension = next === 'audio' ? '.wav' : '.mp4';
    output = output.replace(/\.(mp4|wav)$/i, '') + extension;
  }

  async function pickOutput(): Promise<void> {
    const chosen = await save({
      title: '导出视频',
      defaultPath: output,
      filters: exportVideoClip
        ? [{ name: 'MP4 视频', extensions: ['mp4'] }]
        : [{ name: 'WAV 音频', extensions: ['wav'] }],
    });
    if (chosen) output = chosen;
  }

  /** 把草稿文本夹到 [min, max]; 非法值退回 fallback。 */
  function clampNumber(text: string, fallback: number, min: number, max: number): number {
    const value = Number(text);
    if (!Number.isFinite(value)) return fallback;
    return Math.min(max, Math.max(min, value));
  }

  async function run(): Promise<void> {
    const source = projectPath;
    const target = output.trim();
    if (!source || !target) return;

    phase = 'working';
    errors = [];
    notice = '';
    previewUrl = '';
    progressCurrent = 0;
    progressTotal = 0;
    progressFps = 0;
    cancelRequested = false;
    resultPath = '';
    startedAt = Date.now();
    finishedAt = 0;
    actualEncoder = '';

    try {
      const result = await exportVideo(source, target, startScene, {
        resolution: Number(resolution),
        fps: Math.round(clampNumber(fpsText, 30, 1, 120)),
        bitrateKbps: Number(bitrate),
        encoder,
        fontScale: Number(fontScale),
        autoSpeed: Math.round(clampNumber(autoSpeedText, 12, 0, 100)),
        textSpeed: Math.round(clampNumber(textSpeedText, 24, 0, 100)),
        figureSide: figureSideModern ? 'modern' : 'legacy',
        audioOnly: !exportVideoClip,
        includeAudio,
        uiOnly: !includeStage,
        stageOnly: !includeUi,
        disableFilters: !enableFilters,
        selected,
      });
      resultPath = result.output;
      if (result.encoder) actualEncoder = result.encoder;
      progressCurrent = progressTotal;
      finishedAt = Date.now();
      phase = 'done';
    } catch (error) {
      const message = String(error);
      finishedAt = Date.now();
      if (message.includes('已取消')) {
        // 取消是用户主动行为, 退回表单, 不当成错误。
        startedAt = 0;
        finishedAt = 0;
        phase = 'idle';
        notice = '已取消导出。';
        return;
      }
      phase = 'failed';
      errors = [message];
    }
  }

  /** 在文件管理器里选中产物 (与资源浏览器的「在文件夹中显示」同一 API)。 */
  async function openOutputFolder(): Promise<void> {
    const target = resultPath || output.trim();
    if (!target) return;
    try {
      await revealItemInDir(target);
    } catch (error) {
      errors = [...errors, String(error)];
    }
  }

  async function cancel(): Promise<void> {
    if (cancelRequested) return;
    cancelRequested = true;
    try {
      await cancelVideoExport();
    } catch (error) {
      errors = [String(error)];
    }
  }
</script>

<AppDialog
  title={phase === 'idle'
    ? '导出视频'
    : phase === 'done'
      ? '导出完成'
      : phase === 'failed'
        ? '导出失败'
        : '正在导出视频'}
  iconName="Video"
  size="large"
  height={phase === 'idle' ? 660 : 560}
  closeOnBackdrop={!busy}
  onClose={() => {
    // 导出中不允许直接关窗: 请先「取消」, 否则任务会在后台继续而界面无法再观察。
    if (!busy) onClose();
  }}
>
  {#if phase === 'idle'}
    <div class="video-body">
      {#if status && !status.supported}
        <p class="muted">当前构建未启用视频导出（需要 Windows 且开启 video-export 特性）。</p>
      {/if}
      {#if notice}
        <p class="muted">{notice}</p>
      {/if}

      <section class="settings-group">
        <h3>输出</h3>
        <div class="settings-field">
          <span class="settings-label">文件</span>
          <!-- 只读路径 + 单图标浏览按钮: 与快照对话框同款 (.input-row 让两者同高) -->
          <div class="input-row">
            <input class="ui-input" readonly value={output} title={output} placeholder="选择导出位置" />
            <Button icon="FolderOpen" title="选择输出位置" onclick={() => void pickOutput()} />
          </div>
        </div>
      </section>

      <section class="settings-group">
        <h3>路线</h3>
        <div class="settings-field video-start-scene">
          <span class="settings-label">起始场景</span>
          <Select
            value={startScene}
            options={scenes.map((scene) => ({ value: scene, label: scene }))}
            title="从哪个场景开始导出"
            onchange={changeStartScene}
          />
        </div>

        {#if route.length === 0}
          <p class="muted">从起始场景解析后，这里会列出场景切换与选项。</p>
        {:else}
          <div class="video-route-list">
            {#each route as node, index (index)}
              <div class="video-route-row">
                <span class="video-route-kind">{KIND_LABELS[node.kind] ?? node.kind}</span>
                <span class="video-route-detail" title="{node.scene}:{node.line}">
                  {node.scene}:{node.line}
                </span>
                <div class="video-route-control">
                  {#if node.kind === 'choose'}
                    <Select
                      value={String(node.selected ?? -1)}
                      options={[
                        { value: '-1', label: '在此停止' },
                        ...node.options.map((option, optionIndex) => ({
                          value: String(optionIndex),
                          label: option,
                        })),
                      ]}
                      title="这一处选项导出的分支"
                      onchange={(value) => chooseOption(node, value)}
                    />
                  {:else if node.target}
                    <span class="video-route-target" title={node.target}>
                      <span class="video-route-target-label">目标</span>
                      <span class="video-route-target-name">{node.target}</span>
                    </span>
                  {:else}
                    <span class="video-route-target">
                      <span class="video-route-target-label">结束</span>
                    </span>
                  {/if}
                </div>
              </div>
            {/each}
          </div>
        {/if}
      </section>

      <section class="settings-group">
        <h3>画面</h3>
        <div class="settings-grid">
          <div class="settings-field">
            <span class="settings-label">分辨率</span>
            <Select
              value={resolution}
              options={resolutionChoices}
              title="只选高度；宽度按 game/config.txt 的舞台宽高比推导"
              onchange={(next) => (resolution = next)}
            />
          </div>
          <div class="settings-field">
            <span class="settings-label">帧率</span>
            <Input type="number" bind:value={fpsText} title="每秒帧数" />
          </div>
          <div class="settings-field">
            <span class="settings-label">码率</span>
            <Select
              value={bitrate}
              options={BITRATE_OPTIONS}
              title="视频码率预设"
              onchange={(next) => (bitrate = next)}
            />
          </div>
          <div class="settings-field">
            <span class="settings-label">编码</span>
            <Select
              value={encoder}
              options={ENCODER_OPTIONS}
              title="使用哪种编码后端"
              onchange={(next) => (encoder = next)}
            />
          </div>
        </div>
      </section>

      <section class="settings-group">
        <h3>演出</h3>
        <!-- 与其他参数同一套网格: 所有开关横排, 不再纵向堆五行 -->
        <div class="settings-grid video-performance-grid">
          <div class="settings-field">
            <span class="settings-label">导出内容</span>
            <Select
              value={contentMode}
              options={CONTENT_OPTIONS}
              title="选择导出视频、音频，或两者都导出"
              onchange={changeContentMode}
            />
          </div>
          <div class="settings-field">
            <span class="settings-label">字号</span>
            <Select
              value={fontScale}
              options={FONT_SCALE_OPTIONS}
              title="文本框与姓名的字号缩放"
              onchange={(next) => (fontScale = next)}
            />
          </div>
          <div class="settings-field">
            <span class="settings-label">自动播放速度</span>
            <Input type="number" bind:value={autoSpeedText} title="与 WebGAL 一致：0–100，越大等待越短" />
          </div>
          <div class="settings-field">
            <span class="settings-label">文字显示速度</span>
            <Input type="number" bind:value={textSpeedText} title="与 WebGAL 一致：0–100，越大字出得越快" />
          </div>
        </div>
        <!-- 开关单独一行左对齐: 放进参数网格会被每格居中, 看起来像缩进 -->
        <div class="video-switches">
          <Checkbox checked={includeUi} label="包含文本框与选项" onchange={(checked) => (includeUi = checked)} />
          <Checkbox checked={includeStage} label="包含舞台画面" onchange={(checked) => (includeStage = checked)} />
          <Checkbox checked={enableFilters} label="启用舞台滤镜" onchange={(checked) => (enableFilters = checked)} />
          <Checkbox
            checked={figureSideModern}
            label="依据立绘方位判定切换"
            title="勾选 = WebGAL 4.6.4+（位置也参与立绘身份判定）；不勾选 = 4.6.3 及以前"
            onchange={(checked) => (figureSideModern = checked)}
          />
        </div>
      </section>

      {#if errors.length > 0}
        <div class="video-errors">
          <ul>
            {#each errors.slice(0, 8) as message, index (index)}
              <li>{message}</li>
            {/each}
          </ul>
        </div>
      {/if}
    </div>
  {:else}
    <div class="video-progress">
      <div class="video-progress-main">
        <div class="video-preview" class:video-preview-empty={previewUrl === ''}>
          {#if previewUrl}
            <img src={previewUrl} alt="当前画面" />
          {:else}
            <span class="muted">等待第一帧…</span>
          {/if}
          {#if busy}
            <span class="video-preview-badge">预览</span>
          {/if}
        </div>

        <div class="video-progress-track">
          <div class="video-progress-fill" style="width: {percent}%"></div>
        </div>
        <div class="video-progress-meta">
          <span>
            {#if phase === 'done'}
              导出完成
            {:else if phase === 'failed'}
              导出失败
            {:else if cancelRequested}
              正在取消…
            {:else}
              正在渲染
            {/if}
          </span>
          <span>{percent}%</span>
          <span>{progressTotal > 0 ? `${progressCurrent} / ${progressTotal} 帧` : ''}</span>
          <span>{startedAt > 0 ? `已用 ${elapsedText}` : ''}</span>
          {#if etaText}
            <span>{etaText}</span>
          {/if}
          {#if busy && progressFps > 0}
            <!-- 实际渲染吞吐, 不是配置里的目标帧率 -->
            <span>{Math.round(progressFps)} 帧/s</span>
          {/if}
        </div>

        {#if errors.length > 0}
          <div class="video-errors">
            <ul>
              {#each errors.slice(0, 8) as message, index (index)}
                <li>{message}</li>
              {/each}
            </ul>
          </div>
        {/if}
      </div>

      <aside class="video-summary">
        <h4>配置</h4>
        <dl>
          <dt>文件</dt>
          <dd title={output}>{output}</dd>
          <dt>路线</dt>
          <dd class="video-route-chain">{routeChain}</dd>
          <dt>分辨率</dt>
          <dd>{outputWidth} × {outputHeight}</dd>
          <dt>帧率</dt>
          <dd>{fpsText} fps</dd>
          <dt>码率</dt>
          <dd>{bitrateLabel}</dd>
          <dt>编码</dt>
          <dd>{encoderSummary}</dd>
          <dt>导出内容</dt>
          <dd>{contentLabel}</dd>
          <dt>播放速度</dt>
          <dd>{speedSummary}</dd>
          <dt>字号</dt>
          <dd>{fontScaleLabel}</dd>
          <dt>图层</dt>
          <dd>{layerSummary}</dd>
          <dt>舞台滤镜</dt>
          <dd>{enableFilters ? '开启' : '关闭'}</dd>
        </dl>
      </aside>
    </div>
  {/if}

  {#snippet footer()}
    {#if busy}
      <Button onclick={() => void cancel()} disabled={cancelRequested}>
        {cancelRequested ? '正在取消…' : '取消'}
      </Button>
    {:else if phase === 'done'}
      <Button icon="FolderOpen" onclick={() => void openOutputFolder()}>打开所在目录</Button>
      <Button appearance="primary" onclick={onClose}>完成</Button>
    {:else if phase === 'failed'}
      <Button onclick={() => (phase = 'idle')}>返回设置</Button>
      <Button appearance="primary" onclick={onClose}>关闭</Button>
    {:else}
      <Button onclick={onClose}>关闭</Button>
      <Button appearance="primary" icon="Video" disabled={!canExport} onclick={() => void run()}>开始导出</Button>
    {/if}
  {/snippet}
</AppDialog>
